const CORE=["./", "index.html", "data.js", "game.js", "manifest.webmanifest"];
const key=f=>f+'?v='+FILES[f];
const rel=u=>{try{const p=new URL(u).pathname,s=new URL(self.registration.scope).pathname;return p.startsWith(s)?decodeURIComponent(p.slice(s.length)):'';}catch(_){return '';}};
self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(CACHE).then(async c=>{
 await Promise.allSettled(CORE.map(f=>c.add(new Request(f,{cache:'reload'}))));
 const need=[];
 await Promise.allSettled(Object.keys(FILES).map(async f=>{const k=key(f);if(await c.match(k))return;const r=await caches.match(k);if(r)await c.put(k,r);else need.push(f);}));
 let i=0;const w=async()=>{while(i<need.length){const f=need[i++];try{if(await c.match(key(f)))continue;const r=await fetch(f,{cache:'reload'});if(r.ok)await c.put(key(f),r);}catch(_){}}};
 Promise.all([w(),w(),w(),w()]);
}));});
