const isCore=u=>{const p=new URL(u).pathname;return p.endsWith('/')||/\/(index\.html|game\.js|data\.js|manifest\.webmanifest|sw\.js)$/.test(p);};
self.addEventListener('fetch',e=>{const q=e.request;if(q.method!=='GET')return;
 if(q.mode==='navigate'||isCore(q.url)){e.respondWith(fetch(q,{cache:'no-cache'}).then(r=>{if(r.ok){const k=r.clone();caches.open(CACHE).then(c=>c.put(q,k));}return r;}).catch(()=>caches.match(q,{ignoreSearch:true}).then(r=>r||caches.match('index.html'))));return;}
 e.respondWith(caches.match(q,{ignoreSearch:true}).then(r=>r||fetch(q).then(n=>{if(n.ok){const k=n.clone(),f=rel(q.url);caches.open(CACHE).then(c=>c.put(FILES[f]?key(f):q,k));}return n;})));});
